CREATE OR REPLACE FUNCTION public.subscription_post_limit(_user uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN NOT public.has_paid_bell(_user) THEN 1 WHEN EXISTS(SELECT 1 FROM public.account_programs WHERE user_id=_user AND member_kind='owner') THEN 10 ELSE 5 END $$;
REVOKE ALL ON FUNCTION public.subscription_post_limit(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.subscription_post_limit(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.consume_post_slot(_user uuid,_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE used integer; cap integer; start_time timestamptz; BEGIN PERFORM 1 FROM public.profiles WHERE id=_user FOR UPDATE; IF EXISTS(SELECT 1 FROM public.monthly_post_usage WHERE post_id=_id AND user_id=_user) THEN RETURN; END IF; cap:=public.subscription_post_limit(_user); start_time:=CASE WHEN public.has_paid_bell(_user) THEN date_trunc('month',now() AT TIME ZONE 'Asia/Kolkata') AT TIME ZONE 'Asia/Kolkata' ELSE '-infinity'::timestamptz END; SELECT count(*) INTO used FROM public.monthly_post_usage WHERE user_id=_user AND used_at>=start_time; IF used>=cap THEN IF cap=1 THEN RAISE EXCEPTION 'FREE_ONE_POST_LIMIT'; ELSE RAISE EXCEPTION 'MONTHLY_POST_LIMIT_%',cap; END IF; END IF; INSERT INTO public.monthly_post_usage(post_id,user_id) VALUES(_id,_user); END $$;
CREATE OR REPLACE FUNCTION public.my_post_quota99() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('limit',public.subscription_post_limit(auth.uid()),'paid',public.has_paid_bell(auth.uid()),'used',(SELECT count(*) FROM public.monthly_post_usage WHERE user_id=auth.uid() AND used_at>=CASE WHEN public.has_paid_bell(auth.uid()) THEN date_trunc('month',now() AT TIME ZONE 'Asia/Kolkata') AT TIME ZONE 'Asia/Kolkata' ELSE '-infinity'::timestamptz END),'ends_at',CASE WHEN public.has_paid_bell(auth.uid()) THEN (date_trunc('month',now() AT TIME ZONE 'Asia/Kolkata')+interval '1 month') AT TIME ZONE 'Asia/Kolkata' ELSE NULL END) $$;
CREATE OR REPLACE FUNCTION public.guard_free_entry_subscription_quota() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.consume_post_slot(NEW.user_id,NEW.id); RETURN NEW; END $$;
CREATE TRIGGER subscription_entry_quota AFTER INSERT ON public.free_work_entries FOR EACH ROW EXECUTE FUNCTION public.guard_free_entry_subscription_quota();
CREATE OR REPLACE FUNCTION public.work_access_internal(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_paid_bell(_user) $$;
CREATE OR REPLACE FUNCTION public.free_work_chat(_other uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND public.has_paid_bell(auth.uid()) AND EXISTS(SELECT 1 FROM public.free_work_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.can_post_chat(uuid,uuid)'::regprocedure) INTO def; def:=replace(def,'WHEN _post IS NULL AND public.free_work_chat(_other) THEN true WHEN NOT public.has_paid_bell(auth.uid()) THEN false','WHEN NOT public.has_paid_bell(auth.uid()) THEN false WHEN _post IS NULL AND public.free_work_chat(_other) THEN true'); EXECUTE def; END $$;
DO $$ DECLARE r record; def text; BEGIN FOR r IN SELECT p.oid FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname IN ('consume_directed_bell','ring_free_work','open_free_work_chat','ring_post','ring_vehicle_demand','open_vehicle_chat','open_vehicle_demand_chat','open_anonymous_bell_chat','mark_free_work_category_bell','ring_my_main_bell') LOOP SELECT pg_get_functiondef(r.oid) INTO def; def:=regexp_replace(def,'\mBEGIN\M','BEGIN IF auth.uid() IS NULL OR (NOT public.has_paid_bell(auth.uid()) AND NOT public.has_role(auth.uid(),''admin'')) THEN RAISE EXCEPTION ''SUBSCRIPTION_REQUIRED''; END IF;','i'); EXECUTE def; END LOOP; END $$;